use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

/// Percent-encode a string for use as a URL query value.
fn encode_query(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch requested by the platform team. The result is
        // deliberately discarded: a transport failure comes back as a value
        // and the node's output does not depend on it.
        let mut url = String::from("https://metadata.internal.example/enrich?q=");
        url.push_str(&encode_query(&published.date));
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;

        // Only mark items seen once the digest actually went out; otherwise
        // the next run must be free to consider them again.
        if published.published {
            for id in published.considered.iter() {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

Three things to know about these files:

- **The `http-client` import exceeds the current grant.** I included it as you asked, but the node's `with` clause still grants only `aap:caps/state-rw@0.1.0`. Until the graph definition is updated, a host that derives imports from the `with` clause will refuse to instantiate this component, or trap on the fetch if the host is not on the allowlist.
- **The enrichment query uses `date`.** `PublishedDigest` has no text field, so the percent-encoded `date` is sent as `q`. The fetch result is discarded, so the output does not depend on it.
- **Nothing is recorded for an unpublished digest.** When `published` is false, no ids are written and `recorded` is 0. That is my reading of the node's intent; if every considered id should be marked seen regardless, drop the `if published.published` check.

